     1→import {
     2→  type ClientInterface,
     3→  Membership,
     4→  type RoomInterface,
     5→  type SyncServiceInterface,
     6→  type UserProfile,
     7→} from "@unomed/react-native-matrix-sdk";
     8→import { MatrixJotaiStore } from "../const/matrx-jotai-store";
     9→import { MatrixAtoms } from "../jotai";
    10→
    11→export class MatrixCore {
    12→  public static instance: ClientInterface | null = null;
    13→  public static syncService: SyncServiceInterface | null = null;
    14→  public static profile: UserProfile | null = null;
    15→
    16→  /** Returns the client or throws if not initialized. Eliminates per-method null checks. */
    17→  public static getClient(): ClientInterface {
    18→    if (!MatrixCore.instance) {
    19→      throw new Error("Matrix client is not initialized");
    20→    }
    21→    return MatrixCore.instance;
    22→  }
    23→
    24→  /** Returns the room or throws. Use instead of getClient().getRoom() + manual null check. */
    25→  public static getRoom(roomId: string): RoomInterface {
    26→    const room = MatrixCore.getClient().getRoom(roomId);
    27→    if (!room) throw new Error(`Room not found: ${roomId}`);
    28→    return room;
    29→  }
    30→
    31→  public static getServerName = () => {
    32→    if (!MatrixCore.instance) return null;
    33→    return MatrixCore.instance.server() || MatrixCore.instance.homeserver();
    34→  };
    35→
    36→  /** Sort and store the current room list into Jotai. Called after any membership change. */
    37→  public static refreshRoomList = async () => {
    38→    if (!MatrixCore.instance) return;
    39→
    40→    try {
    41→      const rooms = MatrixCore.instance.rooms();
    42→
    43→      const sortedRooms = await Promise.all(
    44→        rooms.map(async (room) => ({
    45→          room,
    46→          timestamp: (await room.latestEvent())?.timestamp || 0,
    47→        })),
    48→      );
    49→
    50→      const filteredAndSortedRooms = sortedRooms
    51→        .filter(({ room }) => {
    52→          const membership = room.membership();
    53→          return (
    54→            membership !== Membership.Banned &&
    55→            membership !== Membership.Left &&
    56→            membership !== Membership.Knocked
    57→          );
    58→        })
    59→        .sort((a, b) => {
    60→          const aInvited = a.room.membership() === Membership.Invited ? 1 : 0;
    61→          const bInvited = b.room.membership() === Membership.Invited ? 1 : 0;
    62→          if (aInvited !== bInvited) return bInvited - aInvited;
    63→          return Number(b.timestamp) - Number(a.timestamp);
    64→        });
    65→
    66→      MatrixJotaiStore.set(
    67→        MatrixAtoms.roomList,
    68→        filteredAndSortedRooms.map(({ room }) => room),
    69→      );
    70→    } catch (error) {
    71→      console.error("Failed to refresh room list:", error);
    72→    }
    73→  };
    74→}
